<script setup lang="ts">import type{ModerationCase}from"~/composables/useModeration";defineProps<{items:ModerationCase[];activeId?:string}>();defineEmits<{select:[item:ModerationCase]}>();const labels:Record<string,string>={duplicate_exact:"تکراری قطعی",duplicate_likely:"احتمال تکرار",contact_bypass:"تماس در متن",unsafe_image:"تصویر پرریسک",fraud_pattern:"الگوی کلاهبرداری",prohibited_goods:"محتوای ممنوع"};</script>
<template><section class="moderation-queue" aria-label="صف بازبینی"><button v-for="item in items" :key="item.id" type="button" :class="{active:item.id===activeId}" @click="$emit('select',item)"><RiskScoreBadge :score="item.risk_score"/><span><strong>{{item.title}}</strong><small>{{item.city_key}} · {{item.category_slug}}</small><em>{{item.reason_codes.map(code=>labels[code]||code).join('، ')}}</em></span><b v-if="item.state==='appealed'">اعتراض</b></button></section></template>
